def is_inside(path: str) -> bool:
    """True when path stays inside its base directory: relative, and never climbs above it after normalising."""
    pre path.byte_len() > 0
    ex is_inside("sub/../a.txt") == True
    ex is_inside("sub/../../x") == False
    ex is_inside("..") == False
    ex is_inside("/etc/passwd") == False
    if path.startswith("/") or "\\" in path:
        return False
    depth = 0
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of the file at path under the notes directory, or "" when the path leaves notes or the file cannot be read."""
    pre path.byte_len() >= 0
    post out.byte_len() >= 0
    if not is_inside(path):
        return ""
    with fs = fs.sub("notes"):
        body = fs.read_text(path) else ""
    return body
